class Box { public int Value = 10; public string Text = "A"; }
Box Get(Box box) { Print("receiver"); return box; }
int Change(Box box) { Print("rhs"); box.Value = 3; return 3; }
void Main() {
    var box = new Box();
    Print(Get(box).Value += Change(box)); Print(box.Value);
    Print(Get(box).Value /= Change(box)); Print(box.Value);
    Print(Get(box).Value++); Print(++Get(box).Value);
    Print(Get(box).Text += (box.Text = "B")); Print(box.Text);
    Print(false ? Get(box).Value += 100 : box.Value);
    for (var i = 0; i < 2; Get(box).Value += 1, i++) {}
    Print(box.Value);
}
